// UnicodeNames.h — Unicode character names, for `\N{NAME}` escapes.
//
// The table (src/library/UnicodeNameTable.inc, generated by
// tools/gen_unicode_names.py from CPython's unicodedata and NameAliases.txt)
// is compiled into the library: no ICU, no data file, the same on every
// platform.
#pragma once

#include <cstdint>
#include <string_view>

namespace protoPython {
namespace unicode_names {

/** The Unicode version of the table, e.g. "16.0.0". */
const char* unicodeVersion();

/**
 * The code point named `name`, or -1.  Accepts what CPython's `\N{...}`
 * accepts: character names and their aliases (control names such as
 * "LINE FEED", abbreviations such as "NBSP"), in any letter case; the
 * computed names "HANGUL SYLLABLE ..." and "CJK UNIFIED IDEOGRAPH-XXXX" in
 * upper case only.  Named sequences are not characters and are rejected.
 */
int32_t lookup(std::string_view name);

}  // namespace unicode_names
}  // namespace protoPython
